J_{5}=
\tikz[baseline=(M.west)]{%
\node[matrix of math nodes,matrix anchor=west,left delimiter=(,right delimiter=),ampersand replacement=\&] (M) {%
\lambda \& 1 \& 0 \\
0 \& \lambda \& 0 \\
0 \& 0 \& \lambda \\
};
\node[draw,fit=(M-1-1)(M-2-2),inner sep=-1pt] {};
