\addcontentsline{toc}{chapter}{#2}
}
\begin{document}
\tableofcontents
\mychapter{0}{Acknowledgments}
\mychapter{1}{Introduction}
\section{Introduction}
\section{Further Introduction}
\mychapter{2}{Experiments}
\section{Experiment One}
\section{Experiment Two}
\end{document}

