\documentclass{article}
\usepackage[showframe,paper=a4paper,margin=1in]{geometry}% http://ctan.org/pkg/geometry
\usepackage{lipsum}% http://ctan.org/pkg/lipsum
\begin{document}
\begin{titlepage}
\thispagestyle{empty}
